# Writes tables/summary_tables.md from the CSVs in tables/ (run after build_tables.py). Plain python3 is enough.
import csv, pathlib
T = pathlib.Path(__file__).resolve().parent / 'tables'
def rd(n): return list(csv.DictReader(open(T / n)))
out = ['# Summary tables (generated by make_summary_md.py from tables/*.csv - do not edit by hand)\n']
M = rd('maths_runs.csv')
probs = ['digit_sum_double', 'coin_pattern_race', 'round_table_eyes', 'code_trace', 'bitstrings', 'dice_nine', 'makespan']
arms = [('plain max', None), ('plain low', 'kf43'), ('graft2', 'kf43'), ('graft v5', 'kf43')]
out.append('\n## Maths: per problem (first run of each arm; tokens = thinking + visible answer; R = right, x = wrong/no answer)\n\n')
out.append('| problem | ' + ' | '.join(a for a, _ in arms) + ' |\n|---|' + '---|' * len(arms) + '\n')
for p in probs:
    cells = []
    for a, eng in arms:
        rr = [m for m in M if m['arm'] == a and m['problem'] == p and (eng is None or m['engine'] == eng) and not m['engine'].startswith('kf45')]
        if not rr: cells.append('not run'); continue
        m = rr[0]; cells.append(f"{'R' if m['correct'] == 'True' else 'x'} {int(m['total_tokens']):,} tok / {m['minutes']} min" + (f" (think {int(m['thinking_tokens']):,}, answer {int(m['answer_tokens']):,})" if a in ('graft2',) else '') + (' [kf14]' if 'kf14' in m['engine'] else ''))
    out.append(f'| {p} | ' + ' | '.join(cells) + ' |\n')
out.append('\n## Maths: arm totals over the 6 problems every arm solved (round_table separately)\n\n| arm | engine | right | total tokens | thinking | solve | check (after answer found) | visible answer | minutes | round_table |\n|---|---|---|---|---|---|---|---|---|---|\n')
for s in rd('maths_summary_6_shared_problems.csv'):
    out.append(f"| {s['arm']} | {s['engines']} | {s['correct']}/{s['problems']} | {int(s['total_tokens']):,} | {int(s['thinking_tokens']):,} | {int(s['solve_tokens']):,} | {int(s['check_tokens']):,} | {int(s['answer_tokens']):,} | {s['minutes']} | {s['round_table']} ({s['round_table_tokens']} tok) |\n")
A = rd('agentic_runs.csv')
out.append('\n## Agentic: every run (thinking/steps from the dsh transcripts; repeated runs of ag5-base keep only the last transcript)\n\n| tag | arm | engine | task | check | wall s | thinking tok | steps | capped steps | steps with 0 thinking | output tok |\n|---|---|---|---|---|---|---|---|---|---|---|\n')
for a in A:
    out.append(f"| {a['tag']} | {a['arm']} | {a['engine']} | {a['task']} | {a['check']} | {a['wall_s']} | {a.get('thinking_tokens') or '-'} | {a.get('steps') or '-'} | {a.get('capped_steps') or '-'} | {a.get('zero_thinking_steps') or '-'} | {a['output_tokens']} |\n")
out.append('\n## Surprise probe: exact P(no thinking at all on the step) = P(</think> at the first thinking token), by what the last tool result was\n\n| prompt | last tool result | unedited | graft2 | v5 | v7 | original thought |\n|---|---|---|---|---|---|---|\n')
for s in rd('surprise_first_token.csv'):
    out.append(f"| {s['prompt']} | {s['last_tool_result']} | {s['p_no_thinking_unedited']} | {s['p_no_thinking_graft2']} | {s['p_no_thinking_v5']} | {s['p_no_thinking_v7']} | {s['original_thinking_on_that_step']} |\n")
out.append('\n## Analysis task graded against the planted answer key (by hand, not blind)\n\n')
G = rd('analysis_grading.csv'); keys = list(G[0].keys())
out.append('| ' + ' | '.join(keys) + ' |\n|' + '---|' * len(keys) + '\n' + ''.join('| ' + ' | '.join(g[k] for k in keys) + ' |\n' for g in G))
Q = rd('site_browser_checks.csv'); keys = list(Q[0].keys())
out.append('\n## Site task: headless-browser checks (quality_site.cjs)\n\n| ' + ' | '.join(keys) + ' |\n|' + '---|' * len(keys) + '\n' + ''.join('| ' + ' | '.join(q[k] for k in keys) + ' |\n' for q in Q))
(T / 'summary_tables.md').write_text(''.join(out)); print('wrote summary_tables.md')
